若后续取决于知情差异，把已揭晓的事实和人物各自掌握的线索交代清楚。同一条线索，有人亲见，有人听闻，也可能有人仍相信先前的说法。只有材料确立某人被隐瞒、误信或尚未获知时才写出；资料没有提到某人，不足以断定其不知情。最后停在章末已有的事实、未解问题或已约定的行动。篇幅随材料取舍，不为凑齐项目而推测人物内心、预告答案或续写下一章。`});function Es(e){const t=(e?.json?.importedRounds||[]).map((n,r)=>({...n,id:"unbound-"+r,_addedAt:null}));for(const n of gt(e?.summaryHistory)){if(t.push(...(n.importedRounds||[]).map((o,a)=>({...o,id:"import-"+n.endMesId+"-"+a,_addedAt:n.endMesId}))),!n.summary)continue;const r=n.sourceReceipt?.source.start??n.roundSource?.start??n.floorEntry?.source.start??(n.previousEndMesId??-1)+1,s=n.endMesId,i=n.sourceReceipt?.source||n.roundSource;t.push({id:"round-"+s,_addedAt:s,version:n.roundVersion||0,...i&&{origin:{start:i.start,end:i.end,digest:i.digest}},title:"本轮总结",timeLabel:n.kind==="baseline"?"旧档汇总":"#"+(r+1)+(r<s?"–"+(s+1):""),summary:n.summary,...n.memoryTags&&{memoryTags:n.memoryTags},participants:n.memoryTags?.characters||[],memoryRole:"本轮总结"})}return t}function ze(e){return x(e.map(({start:t,end:n,text:r,sourceId:s})=>[t,n,r,s]))}function Se(e){return e.sourceReceipt?.id||e.roundSource&&"round:"+e.roundSource.digest}function gt(e=[],t=[]){const n=new Map;for(const i of e)for(const{end:o,note:a}of[...i.legacyRoundBase||[],...i.legacyRoundChanges||[]])a?n.set(o,a):n.delete(o);const r=e.flatMap(i=>i.roundRevisions||[]).concat(t),s=new Map;for(const i of r){const o=s.get(i.sourceId)||[];o.push(i),s.set(i.sourceId,o)}return e.map(i=>{if(i.floorEntry?.omitted||i.floorEntry?.deleted)return{...i,summary:""};let o=i.summary||i.floorEntry?.payload?.summary||"";const a=n.get(i.endMesId);let d=i.memoryTags,u=i.roundVersion||0;if(a){o=[o,...a.lines.filter(c=>!o.includes(c))].filter(Boolean).join(`
